/* 65a-avatar-pics.js - THE PROFILE PICTURES: hand-made badges (224 px WebP with transparency), one per entry of AVATARS (65-profile.js).
   avatarURL() hands them out as they are; avatarCanvas() draws them onto a canvas (opponent badge, face texture). Made from the artwork
   sheet by cutting out each badge; to replace one, put a new data URL here under the same id. */
const AV_PIC = {
  opa: 'data:image/webp;base64,',
  berserker:
    'data:image/webp;base64,',
  oma: 'data:image/webp;base64,',
  archer:
    'data:image/webp;base64,',
  goat: 'data:image/webp;base64,',
  racer:
    'data:image/webp;base64,',
  omaFlower:
    'data:image/webp;base64,',
  archerStars:
    'data:image/webp;base64,',
  opaShades:
    'data:image/webp;base64,',
  berserkerShades:
    'data:image/webp;base64,',
  opaParty:
    'data:image/webp;base64,',
  omaParty:
    'data:image/webp;base64,',
  berserkerFire:
    'data:image/webp;base64,',
  racerFire:
    'data:image/webp;base64,',
  goatSnow:
    'data:image/webp;base64,',
  archerHalo:
    'data:image/webp;base64,',
  omaMedal:
    'data:image/webp;base64,',
  racerHalo:
    'data:image/webp;base64,',
  berserkerCrown:
    'data:image/webp;base64,',
  opaCrown:
    'data:image/webp;base64,',
  goatCrown:
    'data:image/webp;base64,',
};
// decode them all at the start: avatarCanvas() (opponent face and badge) is synchronous and needs them ready
for (const id in AV_PIC) {
  const im = (AV_IMG[id] = new Image());
  im.src = AV_PIC[id];
}
